<?php
require_once 'config.php';require_login();$pageTitle='Dashboard';
$totalSiswa=(int)$pdo->query('SELECT COUNT(*) FROM siswa')->fetchColumn();$totalP=(int)$pdo->query('SELECT COUNT(*) FROM pelanggaran')->fetchColumn();$totalBaru=(int)$pdo->query("SELECT COUNT(*) FROM pelanggaran WHERE status='Baru'")->fetchColumn();$poin=(int)$pdo->query('SELECT COALESCE(SUM(j.poin),0) FROM pelanggaran p JOIN jenis_pelanggaran j ON j.id_jenis=p.id_jenis')->fetchColumn();
$rows=$pdo->query('SELECT p.*,s.nama_siswa,s.kelas,j.nama_jenis,j.poin FROM pelanggaran p JOIN siswa s ON s.id_siswa=p.id_siswa JOIN jenis_pelanggaran j ON j.id_jenis=p.id_jenis ORDER BY p.tanggal DESC LIMIT 8')->fetchAll();include 'partials/header.php';?>
<div class="welcome"><small>RINGKASAN SEKOLAH</small><h3>Selamat datang, <?=e($_SESSION['user']['nama_lengkap'])?> 👋</h3><p>Pantau kedisiplinan dan tindak lanjut pelanggaran siswa dalam satu tempat.</p></div><div class="stats"><article><span>Total Siswa</span><strong><?=$totalSiswa?></strong><small>Siswa terdaftar</small></article><article><span>Total Pelanggaran</span><strong><?=$totalP?></strong><small>Semua catatan</small></article><article><span>Perlu Ditindaklanjuti</span><strong><?=$totalBaru?></strong><small>Status masih baru</small></article><article><span>Total Poin</span><strong><?=$poin?></strong><small>Akumulasi poin</small></article></div>
<div class="panel"><div class="panel-head"><div><h3>Pelanggaran Terbaru</h3><p>Catatan terakhir yang masuk ke sistem</p></div><a class="btn primary" href="pelanggaran.php">+ Catat Pelanggaran</a></div><div class="table-wrap"><table><thead><tr><th>Siswa</th><th>Kelas</th><th>Jenis</th><th>Poin</th><th>Tanggal</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['nama_siswa'])?></b></td><td><?=e($r['kelas'])?></td><td><?=e($r['nama_jenis'])?></td><td><?=$r['poin']?></td><td><?=e(date('d/m/Y H:i',strtotime($r['tanggal'])))?></td><td><span class="status <?=strtolower($r['status'])?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">Belum ada data. Tambahkan siswa dan catatan pelanggaran untuk memulai.</td></tr><?php endif;?></tbody></table></div></div><?php include 'partials/footer.php';?>
